INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(98589, 'ruRU', '', 'Позволь мне принять на себя основную тяжесть атак Изеры, герой. Можешь на меня положиться: я довольно крепкий.', 24330),
(98600, 'ruRU', '', 'Рыцари крови с тобой, Верховный лорд $p. Азерот не падёт!', 24330),
(98601, 'ruRU', '', 'Добро пожаловать в Небесную Твердыню! Здесь храбрецы живут вечно!', 24330),
(98603, 'ruRU', '', 'Защитник, прости за беспокойство. У меня срочное послание от короля.', 24330),
(98604, 'ruRU', '', 'Штормхейм — дом одного из Столпов Созидания — Эгиды Аграмара.', 24330),
(98605, 'ruRU', '', 'Легенды врайкулов говорят об испытании — пройти его значит доказать свою ценность и заявить права на Эгиду.', 24330),
(98606, 'ruRU', '', 'Наш официальный приказ — сопроводить тебя в Штормхейм и обеспечить твой успех в этом испытании.', 24330),
(98607, 'ruRU', '', 'Впечатляет, правда? Новые орудия способны сбить виверну на полной скорости с трёхсот метров. Давай, взгляни.', 24330),
(98609, 'ruRU', '', 'Неофициально, однако, у нас есть и другая миссия...', 24330),
(98610, 'ruRU', '', '7-й легион. Самые стойкие мужчины и женщины, какие только есть у Альянса. Они тоже прибыли по прямому приказу короля.', 24330),
(98611, 'ruRU', '', 'Три дня назад флот Отрёкшихся отплыл из Дуротара, держа курс прямо на Расколотые острова. Мы полагаем, что сама Сильвана Ветрокрылая может быть среди них.', 24330),
(98612, 'ruRU', '', 'Нам нужно отслеживать их с безопасного расстояния. Мы можем вступить в бой, но только если того потребует обстановка.', 24330),
(98613, 'ruRU', '', 'Я сильно подозреваю, что обстановка этого потребует.', 24330),
(98616, 'ruRU', '', 'Приготовления почти завершены. Прошу, располагайтесь поудобнее.', 24330),
(98622, 'ruRU', '', 'Позволь помочь тебе добраться туда, куда нужно. Пока ты путешествуешь по Расколотым островам, я смогу получать от тебя и новые пункты назначения! Продолжай исследовать!', 24330),
(98629, 'ruRU', '', 'У меня в наличии широкий выбор рецептов.', 24330),
(98635, 'ruRU', '', 'Защитник: как твой новый вождь, я разделяю с тобой бремя обеспечения нашего будущего.', 24330),
(98636, 'ruRU', '', 'Ради этого мой флот готовится отплыть к Расколотым островам. Когда ты ступишь в Штормхейм, за твоей спиной будет вся мощь Отрёкшихся.', 24330),
(98637, 'ruRU', '', 'Отправляйся в путь с нами. Вместе мы добьёмся того, что никто не сможет противостоять мощи Орды!', 24330),
(98638, 'ruRU', '', 'Разве наш алхимический стол не чудо? Дьюкус потратил годы на сборку его компонентов. Он так им гордится!', 24330),
(98641, 'ruRU', '', 'Ты знаком с врайкулами? Исполинские, грубые воины древнего рода. Утончённость не входит в число их ценностей.', 24330),
(98645, 'ruRU', '', 'Эта ужасная Свена разгромила алхимический стол. Бедный Дьюкус! Знаю, он это скрывает, но у него разбито сердце.$b$bОчень надеюсь, что ты сможешь помочь ему закончить его восстановление!', 24330),
(98646, 'ruRU', '', 'Их легенды говорят об Эгиде Аграмара. Чтобы заявить на неё права, нужно пройти какое-то испытание. Нужно быть... достойным.', 24330),
(98648, 'ruRU', '', 'Алхимический стол выглядит потрясающе! Дьюкус испытал такое облегчение. Спасибо за всю работу, что ты проделал, восстанавливая его.$b$bБудем надеяться, что мы больше никогда не увидим призрака врайкула в мастерской!', 24330),
(98650, 'ruRU', '', 'Новые катапульты быстрее и мощнее, чем когда-либо прежде. За это стоит благодарить наших союзников-гоблинов.', 24330),
(98651, 'ruRU', '', 'Уверен, ты более чем способен справиться с любыми испытаниями, что стоят между тобой и Эгидой.', 24330),
(98652, 'ruRU', '', 'По правде говоря, Штормхейм хранит ещё одно сокровище. То, за которым я буду охотиться собственными силами.', 24330),
(98653, 'ruRU', '', '<На мгновение отвлёкшись от своего бдения, величественная друидесса оборачивается и смотрит на тебя. Её тёмные глаза расширяются в узнавании и тепле.>$b$b<Без единого слова она даёт понять, что тебе здесь всегда рады.>', 24330),
(98654, 'ruRU', '', 'Натанос обучает новое поколение следопытов. Они олицетворяют и наше прошлое, и наше будущее.', 24330),
(98655, 'ruRU', '', 'Я часто думаю о нашем будущем, герой. Мой народ не может размножаться. Разве не суждено нам тогда в конце концов увянуть?', 24330),
(98656, 'ruRU', '', 'Нет. Отрёкшиеся никогда не прекратят борьбу.', 24330),
(98657, 'ruRU', '', 'Не пока я правлю. Не пока существуют те, у кого есть сила остановить смерть.', 24330),
(98658, 'ruRU', '', 'Вести от капитана Жуткой Волны, моя госпожа. Они нашли храм.', 24330),
(98659, 'ruRU', '', '"Забвение" высадилось неподалёку. Сейчас они возводят укрепления и будут готовы начать осаду по твоему приказу.', 24330),
(98660, 'ruRU', '', 'Хорошо. Отправь нетопыря — передай им, что мы скоро выдвигаемся.', 24330),
(98666, 'ruRU', '', 'Я продаю рецепты, которые мы с Дьюкусом исследуем вместе. По мере изучения новых я добавляю их в свой ассортимент.$b$bЗаглядывай время от времени, чтобы узнать, не появилось ли что-то новое!', 24330),
(98669, 'ruRU', '', 'Я избранница Эйир! Какой, по-твоему, у тебя шанс?', 24330),
(98670, 'ruRU', '', 'Я живу. Я умираю. Я...', 24330),
(98705, 'ruRU', '', 'Полегче. Это снадобье требует времени. Тебе нужно отдохнуть.', 24330),
(98708, 'ruRU', '', 'Стражи ищут нашей помощи? Должно быть, дела совсем плохи.', 24330);
